        const { socket, contentLength, client, bytesWritten, expectsPayload, header, request } =
          this;
        request.onRequestSent();

        socket[kWriting] = false;

        if (socket[kError]) {
          throw socket[kError];
        }

        if (socket.destroyed) {
          return;
        }

